import React from 'react';
import { Link } from 'react-router-dom';
import '../assets/styles.css';
import '../assets/home-dark.css';
import '../assets/server-theme.css';

import logoNuevo from '../assets/img/logonuevo.png';
import UserMenu from '../components/UserMenu.jsx';

import mapaActual from '../assets/img/maparustacooo.png';
import mapaAnterior from '../assets/img/mapa1.png';

const DISCORD_URL = 'https://discord.rustaco.site';
const STORE_URL = 'https://store.rustaco.co';
const SUPPORT_URL = 'https://discord.rustaco.site';

// ─── EDITA AQUÍ LOS DATOS DEL MAPA ─────────────────────────────────────────
const CURRENT_MAP = {
  image: mapaActual,
  name: 'Procedural Map',
  size: '4000',
  seed: '—',
  wipe: 'Jueves',
  rustmaps: '', // URL de rustmaps.com del mapa actual (opcional)
};

// Mapas de wipes anteriores (galería). Deja el array vacío [] si no quieres mostrarla.
const MAP_HISTORY = [
  { image: mapaAnterior, label: 'Wipe anterior' },
];
// ───────────────────────────────────────────────────────────────────────────

export default function Maps() {
  const [lightbox, setLightbox] = React.useState(null);

  React.useEffect(() => {
    document.body.classList.add('has-video-bg');
    return () => document.body.classList.remove('has-video-bg');
  }, []);

  React.useEffect(() => {
    if (!lightbox) return undefined;
    const onKey = (event) => {
      if (event.key === 'Escape') setLightbox(null);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [lightbox]);

  return (
    <div className="rw-page">
      <header className="rw-nav">
        <Link to="/" className="rw-nav-brand">
          <img src={logoNuevo} alt="Rustaco" />
          <span>
            Rust<em>aco</em>
          </span>
        </Link>

        <nav className="rw-nav-links" aria-label="Navegación">
          <Link to="/" className="rw-nav-link">Inicio</Link>
          <a href={STORE_URL} target="_blank" rel="noopener noreferrer" className="rw-nav-link">Store</a>
          <Link to="/rules" className="rw-nav-link">Reglas</Link>
          <span className="rw-nav-link" style={{ color: '#fff' }} aria-current="page">
            Maps
          </span>
          <Link to="/events" className="rw-nav-link">Leaderboard</Link>
          <a href={SUPPORT_URL} target="_blank" rel="noopener noreferrer" className="rw-nav-link">Soporte</a>
          <a href={DISCORD_URL} target="_blank" rel="noopener noreferrer" className="rw-nav-link">
            Discord
          </a>
        </nav>

        <div className="rw-nav-right">
          <UserMenu />
          <a className="rw-btn rw-btn--discord rw-btn--sm" href={DISCORD_URL} target="_blank" rel="noopener noreferrer">
            <i className="bi bi-discord" /> Discord
          </a>
        </div>
      </header>

      <main className="rw-lb-main">
        <div className="rw-lb-head">
          <span className="rw-section-kicker">Mapa del wipe</span>
          <h1>Maps</h1>
          <p>
            Consulta el mapa actual del servidor, su tamaño y semilla. El mapa se renueva
            en cada map wipe para mantener el juego fresco.
          </p>
        </div>

        {/* ── Mapa actual ── */}
        <section className="rw-map-current">
          <button
            type="button"
            className="rw-map-figure"
            onClick={() => setLightbox(CURRENT_MAP.image)}
            title="Ampliar mapa"
          >
            <img src={CURRENT_MAP.image} alt={`Mapa actual: ${CURRENT_MAP.name}`} />
            <span className="rw-map-zoom">
              <i className="bi bi-zoom-in" /> Ampliar
            </span>
            <span className="rw-map-livetag">
              <i className="bi bi-broadcast" /> Mapa en vivo
            </span>
          </button>

          <aside className="rw-map-info">
            <h2>{CURRENT_MAP.name}</h2>
            <dl className="rw-map-meta">
              <div>
                <dt><i className="bi bi-aspect-ratio" /> Tamaño</dt>
                <dd>{CURRENT_MAP.size}</dd>
              </div>
              <div>
                <dt><i className="bi bi-hash" /> Seed</dt>
                <dd>{CURRENT_MAP.seed}</dd>
              </div>
              <div>
                <dt><i className="bi bi-arrow-repeat" /> Map wipe</dt>
                <dd>{CURRENT_MAP.wipe}</dd>
              </div>
            </dl>

            <div className="rw-map-actions">
              {CURRENT_MAP.rustmaps ? (
                <a
                  className="rw-btn rw-btn--primary rw-btn--sm"
                  href={CURRENT_MAP.rustmaps}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <i className="bi bi-box-arrow-up-right" /> Ver en RustMaps
                </a>
              ) : null}
              <button
                className="rw-btn rw-btn--ghost rw-btn--sm"
                type="button"
                onClick={() => setLightbox(CURRENT_MAP.image)}
              >
                <i className="bi bi-arrows-fullscreen" /> Pantalla completa
              </button>
            </div>

            <p className="rw-map-note">
              <i className="bi bi-info-circle" /> El tamaño y la semilla del próximo wipe se
              anuncian en nuestro Discord antes de cada renovación.
            </p>
          </aside>
        </section>

        {/* ── Historial de mapas ── */}
        {MAP_HISTORY.length > 0 && (
          <section className="rw-map-history">
            <div className="rw-rules-sectionhead">
              <i className="bi bi-clock-history" aria-hidden="true" />
              <h2>Wipes anteriores</h2>
            </div>
            <div className="rw-map-grid">
              {MAP_HISTORY.map((item) => (
                <button
                  key={item.label}
                  type="button"
                  className="rw-map-thumb"
                  onClick={() => setLightbox(item.image)}
                  title={`Ampliar: ${item.label}`}
                >
                  <img src={item.image} alt={item.label} />
                  <span>{item.label}</span>
                </button>
              ))}
            </div>
          </section>
        )}
      </main>

      {/* ── Lightbox ── */}
      {lightbox && (
        <div className="rw-lightbox" role="presentation" onClick={() => setLightbox(null)}>
          <button className="rw-lightbox-close" type="button" aria-label="Cerrar">
            <i className="bi bi-x-lg" />
          </button>
          <img
            src={lightbox}
            alt="Mapa ampliado"
            onClick={(event) => event.stopPropagation()}
          />
        </div>
      )}

      <footer className="rw-footer">
        <div className="rw-footer-brand">
          <img src={logoNuevo} alt="Rustaco" />
          <span>© Rustaco — Todos los derechos reservados.</span>
        </div>
        <nav className="rw-footer-links">
          <Link to="/">Inicio</Link>
          <Link to="/rules">Reglas</Link>
          <Link to="/events">Leaderboard</Link>
          <a href={DISCORD_URL} target="_blank" rel="noopener noreferrer">Discord</a>
        </nav>
      </footer>
    </div>
  );
}
